    id: ctx.allocateUnitId(),
    ownerId: toOwnerId,
    typeId: unitTypeId,
    category: categoryOf(unitTypeId, role, isSuper),
    q: placement.q,
    r: placement.r,
    ruch,
    ruchLeft: ruch
